window.kbPageData["views/entry/k-4b3c135664acff90"] = {"key":"entry/k-4b3c135664acff90","state":{"route":"entry/k-4b3c135664acff90"},"node":{"id":"k-4b3c135664acff90","mode":"k","title":"学前一年免费教育政策","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["modern"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2025,"title":"学前一年免费教育政策","slug":"44797827bb7c"}],"directorySummary":"3.学前一年免费教育政策\n从 2025 年秋季学期起，免除公办幼儿园学前一年在园儿童保育教育费。对在教育部门\n批准设立的民办幼儿园就读的适龄儿童，参照当地同类型公办幼儿园免除水平，相应减免保\n育教育费。财政部、教育部将统筹考虑学龄人口变化、财力状况等因素，研究适时完善免费\n学前教育政策。西藏，四川、…","sources":[{"id":"673b944789a70a1d","label":"学前一年免费教育政策","topic":"年度政府工作","category":"时政","text":"3.学前一年免费教育政策\n从 2025 年秋季学期起，免除公办幼儿园学前一年在园儿童保育教育费。对在教育部门\n批准设立的民办幼儿园就读的适龄儿童，参照当地同类型公办幼儿园免除水平，相应减免保\n育教育费。财政部、教育部将统筹考虑学龄人口变化、财力状况等因素，研究适时完善免费\n学前教育政策。西藏，四川、云南、甘肃、青海四省涉藏州县，新疆喀什、和田、阿克苏、\n克孜勒苏柯尔克孜四地州等地区在园儿童继续执行现行政策。\n——《国务院办公厅关于逐步推行免费学前教育的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-4b3c135664acff90":[]}};
